assert len(DATA) == 10
TARGETS = ["C", "B", "B", "A", "A", "A", "B", "A", "A", "A"]
for i, (prompt, options, answer, explanation, strategy, steps) in enumerate(DATA, 1):
    original = answer
    target = TARGETS[i - 1]
    if target != original:
        oi, ti = ord(original) - ord("A"), ord(target) - ord("A")
        correct = options[oi]
        rest = [v for j, v in enumerate(options) if j != oi]
        options = rest[:ti] + [correct] + rest[ti:]
        explanation = explanation.replace(f"{original} ", f"{target} ")
        strategy = strategy.replace(f"{original} ", f"{target} ")
        steps = [s.replace(f"{original} ", f"{target} ") for s in steps]
        answer = target
    item = {"id": f"question-chinese-content-bd-iv-1-{i}", "subject": "chinese", "type": "single-choice", "prompt": prompt, "options": [{"id": chr(65+j), "text": t} for j, t in enumerate(options)], "knowledgeIds": ["kg-chinese-content-bd-iv-1"], "difficulty": "medium", "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "公立學校公開國文段考與課程資料；只研究事實、理論、價值主張、論據、外推與反例。", "authoringNote": "依官方語文領域課綱、單元 KG 與三個公立學校公開來源，獨立改寫論證與批判題；未複製原文、選項、篇章、圖片或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-13", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}
